+   /**
+    * Resolve a child path against a base directory and verify the resulting
+    * canonical path is contained within the base directory. This prevents path
+    * traversal (zip slip) attacks where zip entries contain "../" segments or
+    * absolute paths.
+    *
+    * @param baseDirectory The directory into which files should be extracted.
+    * @param entryName The entry name from the zip file.
+    * @return A File representing the resolved destination.
+    * @throws IOException If an I/O error occurs or the resolved path is outside the base.
+    */
+   private static File resolveFileWithinDirectory(File baseDirectory, String entryName) throws IOException
+   {
+      if (baseDirectory == null)
+      {
+         throw new IllegalArgumentException("baseDirectory must not be null");
+      }
+
+      // Construct the destination file and resolve canonical paths to eliminate
+      // any ../ segments and symlink differences.
+      File dest = new File(baseDirectory, entryName);
+
+      String baseCanonical = baseDirectory.getCanonicalPath();
+      String destCanonical = dest.getCanonicalPath();
+
+      // Ensure the destination is within the base directory. Append a separator
+      // to the base to prevent partial matching (e.g. /baseDir2 when base is /base).
+      String baseWithSep = baseCanonical.endsWith(File.separator) ? baseCanonical : baseCanonical + File.separator;
+
+      if (!destCanonical.equals(baseCanonical) && !destCanonical.startsWith(baseWithSep))
+      {
+         throw new IOException("Zip entry '" + entryName + "' would be extracted outside of the target directory: " + destCanonical);
+      }
+
+      return dest;
+   }
