+  // Render heading safely: when HTML is disabled (no-html), ensure any raw/html_inline
+  // tokens are escaped instead of being injected as markup. This preserves normal
+  // inline markdown formatting (em, strong, links, etc.) while neutralizing
+  // user-supplied raw HTML in headers that could lead to XSS.
+  const renderInlineSafe = function (children, options, env) {
+    if (!children || !children.length) {
+      return '';
+    }
+
+    // If HTML is allowed, fall back to the default inline renderer for performance.
+    if (options && options.html) {
+      return md.renderer.renderInline(children, options, env);
+    }
+
+    // HTML is disabled: render each child token, but escape any html_inline tokens.
+    return children.map((child) => {
+      if (child.type === 'html_inline') {
+        // Escape raw HTML so it cannot execute as markup/event handlers.
+        return md.utils.escapeHtml(child.content);
+      }
+      // Render other inline tokens (emphasis, links, code, etc.) normally.
+      return md.renderer.renderInline([child], options, env);
+    }).join('');
+  };
+
+  md.renderer.rules.heading_open = function (tokens, idx, options, env, self) {
+    const next = tokens[idx + 1];
+    const title = next && next.type === 'inline'
+      ? renderInlineSafe(next.children, options, env)
+      : '';
+
+    const level = tokens[idx].tag.slice(1);
+    const slug = slugify(title);
+
+    return `<${tokens[idx].tag} id="${slug}">${title}</${tokens[idx].tag}>`;
