+// filters a populate object/array/string based on allowed fields
+// Ensure authorization checks use the full path for nested populates.
+const filterPopulate = (populate, allowedFields, parent = '') => {
+  if (!populate) {
+    return populate;
+  }
+
+  // helper: check whether a full path is allowed
+  const isAllowedPath = (fullPath) => {
+    // exact match or any permitted parent path (e.g. 'comments' allows 'comments.author')
+    if (allowedFields.includes(fullPath)) return true;
+    // allow if the root segment is allowed (so 'comments' in allowedFields allows 'comments.author')
+    const root = fullPath.split('.')[0];
+    return allowedFields.includes(root);
+  };
+
+  // normalize string populate like 'author,comments.author'
+  if (typeof populate === 'string') {
+    return populate
+      .split(',')
+      .map((p) => p.trim())
+      .filter((p) => {
+        const full = parent ? `${parent}.${p}` : p;
+        return isAllowedPath(full);
+      })
+      .join(',');
+  }
+
+  if (Array.isArray(populate)) {
+    return populate
+      .map((p) => filterPopulate(p, allowedFields, parent))
+      .filter(Boolean);
+  }
+
+  // object form
+  if (typeof populate === 'object') {
+    const result = {};
+    Object.keys(populate).forEach((key) => {
+      const fullPath = parent ? `${parent}.${key}` : key;
+      if (isAllowedPath(fullPath)) {
+        // keep nested populate but continue filtering inside
+        result[key] = filterPopulate(populate[key], allowedFields, fullPath);
+      }
+    });
+
+    return result;
+  }
+
+  // unknown type, just return as-is
