+// Ensure directory exists without TOCTOU: try to create and handle errors
+// Avoid using fs.existsSync() followed by fs.mkdirSync() because that is
+// susceptible to race conditions (CWE-367). This implementation attempts
+// to create the directory and only falls back to creating parents when
+// needed, checking for legitimate EEXIST conditions.
+exports.mkdirpSync = function mkdirpSync (dir) {
+  try {
+    fs.mkdirSync(dir);
+    return;
