+    if (err.code === 'ENOENT') {
+      // Parent doesn't exist — ensure parent first, then retry.
+      var parent = path.dirname(dir);
+      // If parent is same as dir (root), rethrow
+      if (parent === dir) {
+        throw err;
+      }
