+/**
+ * Middleware to enforce authorization for protected routes.
+ *
+ * This replaces ad-hoc or missing checks and ensures server-side session/token
+ * data is used to authorize state-changing operations.
+ *
+ * Expected shape of req.user:
+ *   - req.user.id
+ *   - req.user.roles: array of role names (optional)
+ *   - req.user.permissions: array of permission strings (optional)
+ *
+ * The middleware will:
+ *   - return 401 if the request is unauthenticated (no req.user)
+ *   - return 403 if the authenticated user lacks the required permission/role
+ *
+ * Minimal, explicit checks are used to avoid leaking information about resources.
+ */
+module.exports = function requirePermission(requiredPermissionOrRole) {
+  return function (req, res, next) {
+    // Authentication check
+    const user = req.user || (req.session && req.session.user);
+    if (!user) {
+      // Not authenticated
+      return res.status(401).json({ error: 'Authentication required' });
+    }
+
+    // Normalize permission/role sources
+    const permissions = Array.isArray(user.permissions) ? user.permissions : [];
+    const roles = Array.isArray(user.roles) ? user.roles : [];
+
+    // Simple checks: either the permission exists, or the user has an 'admin' role,
+    // or the explicit role name matches.
+    if (permissions.includes(requiredPermissionOrRole) ||
+        roles.includes(requiredPermissionOrRole) ||
+        roles.includes('admin')) {
+      return next();
+    }
+
+    // Forbidden: user authenticated but not authorized
+    return res.status(403).json({ error: 'Forbidden' });
+  };
+};
